if($method==='POST'&&$path==='gateway/pair'){rate_limit('pair',10,600);$code=strtoupper(trim((string)($data['pairing_code']??'')));if(!preg_match('/^[A-F0-9]{8}$/',$code))json_out(['error'=>'invalid_code'],422);$q=$pdo->prepare('SELECT id,name FROM gateways WHERE pairing_hash=? AND pairing_expires>? AND enabled=1');$q->execute([hash('sha256',$code),gmdate('Y-m-d H:i:s')]);$g=$q->fetch();if(!$g)json_out(['error'=>'expired_or_invalid_code'],401);$token=rtrim(strtr(base64_encode(random_bytes(48)),'+/','-_'),'=');$pdo->prepare('UPDATE gateways SET api_token_hash=?,pairing_hash=NULL,pairing_expires=NULL,device_model=?,android_version=?,app_version=?,phone_number=?,operator_name=?,status=\'online\',last_seen=CURRENT_TIMESTAMP WHERE id=?')->execute([hash('sha256',$token),substr((string)($data['device_model']??''),0,120),substr((string)($data['android_version']??''),0,40),substr((string)($data['app_version']??''),0,40),normalize_phone((string)($data['phone_number']??'')),substr((string)($data['operator']??''),0,80),$g['id']]);notify_telegram('gateway_online','Gateway آنلاین شد: '.$g['name']);json_out(['token'=>$token,'gateway_id'=>(int)$g['id'],'name'=>$g['name']]);}
